//! WebAssembly bindings for `plan-core`. The browser holds one `PlanEngine` per open project.
//! All complex values cross the boundary as plain JS objects (serde-wasm-bindgen), shaped like the
//! TS types generated by ts-rs (`web/src/core/generated`).

use plan_core::commands::{self, ChainPoint};
use plan_core::furniture;
use plan_core::geom::P;
use plan_core::mesh::scene_meshes;
use plan_core::primitives::{primitive_mesh, PrimitiveShape};
use plan_core::rooms::derive_rooms;
use plan_core::sun::sun_position;
use plan_core::validate::validate;
use plan_core::walls::footprints;
use plan_core::{apply_batch, FurnitureInstance, Id, Op, OpError, Project, WallKind};
use serde::Serialize;
use wasm_bindgen::prelude::*;

fn to_js<T: Serialize>(v: &T) -> Result<JsValue, JsError> {
    let ser = serde_wasm_bindgen::Serializer::json_compatible();
    v.serialize(&ser).map_err(|e| JsError::new(&e.to_string()))
}
fn from_js<T: serde::de::DeserializeOwned>(v: JsValue) -> Result<T, JsError> {
    serde_wasm_bindgen::from_value(v).map_err(|e| JsError::new(&e.to_string()))
}
fn op_err(e: OpError) -> JsError {
    JsError::new(&e.to_string())
}
fn id(s: &str) -> Result<Id, JsError> {
    s.parse().map_err(|_| JsError::new("ungültige ID"))
}

#[wasm_bindgen(start)]
pub fn start() {
    console_error_panic_hook::set_once();
}

#[wasm_bindgen]
pub struct PlanEngine {
    project: Project,
    colliders: Option<Vec<Vec<P>>>,
    /// Shut doors (view state) block walking.
    closed_doors: std::collections::HashSet<Id>,
}

#[wasm_bindgen]
impl PlanEngine {
    #[wasm_bindgen(constructor)]
    pub fn new(project: JsValue) -> Result<PlanEngine, JsError> {
        Ok(PlanEngine { project: from_js(project)?, colliders: None, closed_doors: Default::default() })
    }

    pub fn project(&self) -> Result<JsValue, JsError> {
        to_js(&self.project)
    }

    pub fn set_project(&mut self, project: JsValue) -> Result<(), JsError> {
        self.project = from_js(project)?;
        self.colliders = None;
        Ok(())
    }

    pub fn set_version(&mut self, version: f64) {
        self.project.version = version as u64;
    }

    /// Apply a batch atomically; returns the inverse batch.
    pub fn apply(&mut self, ops: JsValue) -> Result<JsValue, JsError> {
        let ops: Vec<Op> = from_js(ops)?;
        let inv = apply_batch(&mut self.project, &ops)
            .map_err(|(i, e)| JsError::new(&format!("Operation {}: {}", i + 1, e)))?;
        self.colliders = None;
        to_js(&inv)
    }

    // ---- commands (return ops, do not apply) ----

    pub fn cmd_add_wall_chain(&self, floor: &str, points: JsValue, closed: bool, thickness_mm: u32, exterior: bool) -> Result<JsValue, JsError> {
        let pts: Vec<ChainPoint> = from_js(points)?;
        let kind = if exterior { WallKind::Exterior } else { WallKind::Interior };
        to_js(&commands::add_wall_chain(&self.project, id(floor)?, &pts, closed, thickness_mm, kind).map_err(op_err)?)
    }
    pub fn cmd_split_wall(&self, floor: &str, wall: &str, x: i32, y: i32) -> Result<JsValue, JsError> {
        to_js(&commands::split_wall(&self.project, id(floor)?, id(wall)?, x, y).map_err(op_err)?)
    }
    pub fn cmd_delete_wall(&self, floor: &str, wall: &str) -> Result<JsValue, JsError> {
        to_js(&commands::delete_wall(&self.project, id(floor)?, id(wall)?).map_err(op_err)?)
    }
    pub fn cmd_delete_node(&self, floor: &str, node: &str) -> Result<JsValue, JsError> {
        to_js(&commands::delete_node(&self.project, id(floor)?, id(node)?).map_err(op_err)?)
    }
    pub fn cmd_merge_nodes(&self, floor: &str, keep: &str, remove: &str) -> Result<JsValue, JsError> {
        to_js(&commands::merge_nodes(&self.project, id(floor)?, id(keep)?, id(remove)?).map_err(op_err)?)
    }
    pub fn cmd_move_wall(&self, floor: &str, wall: &str, offset_mm: f64) -> Result<JsValue, JsError> {
        to_js(&commands::move_wall(&self.project, id(floor)?, id(wall)?, offset_mm).map_err(op_err)?)
    }
    pub fn cmd_set_wall_length(&self, floor: &str, wall: &str, length_mm: u32, fixed_a: bool) -> Result<JsValue, JsError> {
        to_js(&commands::set_wall_length(&self.project, id(floor)?, id(wall)?, length_mm, fixed_a).map_err(op_err)?)
    }
    pub fn cmd_delete_furniture(&self, item: &str) -> Result<JsValue, JsError> {
        to_js(&commands::delete_furniture(&self.project, id(item)?).map_err(op_err)?)
    }
    /// Copies of furniture (with their lamps) and lamps, moved by (dx, dy): `[ops, newIds]`.
    pub fn cmd_duplicate(&self, ids: JsValue, dx: i32, dy: i32) -> Result<JsValue, JsError> {
        let ids: Vec<Id> = from_js(ids)?;
        to_js(&commands::duplicate(&self.project, &ids, [dx, dy]).map_err(op_err)?)
    }
    /// Ops that put `template` (a Light) on a surface point with outward normal; `furniture` = '' for none.
    #[allow(clippy::too_many_arguments)]
    pub fn cmd_place_light(&self, template: JsValue, x: f64, y: f64, z: f64, nx: f64, ny: f64, nz: f64, furniture: &str) -> Result<JsValue, JsError> {
        let t: plan_core::Light = from_js(template)?;
        let f = if furniture.is_empty() { None } else { Some(id(furniture)?) };
        let l = plan_core::lights::place_light(&self.project, t, [x, y, z], [nx, ny, nz], f);
        to_js(&vec![plan_core::Op::PutLight { light: l }])
    }
    pub fn cmd_transform_floor(&self, floor: &str, scale: f64, ox: f64, oy: f64, tx: f64, ty: f64) -> Result<JsValue, JsError> {
        to_js(&commands::transform_floor(&self.project, id(floor)?, scale, [ox, oy], [tx, ty]).map_err(op_err)?)
    }
    /// Ops that turn this engine's project into `other`.
    pub fn diff_to(&self, other: JsValue) -> Result<JsValue, JsError> {
        let other: Project = from_js(other)?;
        to_js(&commands::diff(&self.project, &other))
    }

    // ---- derived data ----

    pub fn rooms(&self, floor: &str) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        to_js(&derive_rooms(f))
    }
    pub fn footprints(&self, floor: &str) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        to_js(&footprints(f))
    }
    pub fn validate(&self, floor: &str) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        to_js(&validate(f))
    }
    pub fn scene_meshes(&self, floor: &str) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        to_js(&scene_meshes(f))
    }
    pub fn snap_furniture(&self, floor: &str, x: f64, y: f64, dims: Vec<u32>, rotation_deg: f64, threshold_mm: f64) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        let d = [dims.first().copied().unwrap_or(1), dims.get(1).copied().unwrap_or(1), dims.get(2).copied().unwrap_or(1)];
        to_js(&furniture::snap_to_wall(f, x, y, d, rotation_deg, threshold_mm))
    }
    pub fn clearances(&self, floor: &str, item: JsValue) -> Result<JsValue, JsError> {
        let f = self.project.floor(id(floor)?).ok_or_else(|| JsError::new("Stockwerk fehlt"))?;
        let item: FurnitureInstance = from_js(item)?;
        to_js(&furniture::clearances(f, &item))
    }
    /// Ids of furniture overlapping other furniture or walls.
    pub fn overlaps(&self) -> Result<JsValue, JsError> {
        to_js(&furniture::overlaps(&self.project))
    }
    /// Floor height (mm) at plan point: top of a podium there (ignoring furniture `except`, may be empty), else 0.
    pub fn floor_height_at(&self, x: f64, y: f64, except: &str) -> f64 {
        furniture::floor_height_at(&self.project, [x, y], Id::parse_str(except).ok())
    }
    /// Doors that are shut (ids); they block walking until opened again.
    pub fn set_closed_doors(&mut self, ids: JsValue) -> Result<(), JsError> {
        let ids: Vec<String> = from_js(ids)?;
        self.closed_doors = ids.iter().filter_map(|s| Id::parse_str(s).ok()).collect();
        self.colliders = None;
        Ok(())
    }

    /// Move the walker (plan mm). Returns [x, y].
    pub fn walk_move(&mut self, x: f64, y: f64, dx: f64, dy: f64, radius: f64) -> Vec<f64> {
        if self.colliders.is_none() {
            self.colliders = Some(furniture::walk_colliders_closed(&self.project, &self.closed_doors));
        }
        let p = furniture::walk_move(self.colliders.as_ref().unwrap(), [x, y], [dx, dy], radius);
        vec![p[0], p[1]]
    }
}

/// Sun position for local clock time. `minutes` after midnight, `utc_offset_min` = local − UTC.
#[wasm_bindgen]
pub fn sun(lat: f64, lon: f64, year: i32, month: u32, day: u32, minutes: f64, utc_offset_min: f64) -> Result<JsValue, JsError> {
    to_js(&sun_position(lat, lon, year, month, day, minutes, utc_offset_min))
}

/// Mesh for a primitive shape (metres, origin bottom centre, front +Z). `shape` e.g. "Sofa".
#[wasm_bindgen]
pub fn primitive(shape: JsValue, w_mm: u32, d_mm: u32, h_mm: u32) -> Result<JsValue, JsError> {
    let s: PrimitiveShape = from_js(shape)?;
    to_js(&primitive_mesh(s, [w_mm, d_mm, h_mm]))
}

#[wasm_bindgen]
pub fn new_id() -> String {
    uuid::Uuid::new_v4().to_string()
}
